#!/usr/bin/env python3
"""The exact frozen One-off Graph Programming v1 experiment surface."""
import contextlib, fcntl, io, json, os, sys, time
from pathlib import Path
from mcp_server.retrieve import Retrieve
from mcp_server.surface import Surface
from research.abstraction_frontier.treatment import ExcludedEphemeralOperation, validate_frozen_ephemeral_program

ALLOWED = {"describe", "lookup", "expand", "path", "run_ephemeral_traversal"}
def walk(value, key):
    out=[]
    if isinstance(value, dict):
        for k,v in value.items():
            if k == key and isinstance(v,str): out.append(v)
            out.extend(walk(v,key))
    elif isinstance(value,list):
        for v in value: out.extend(walk(v,key))
    return sorted(set(out))
def audit(event):
    event["order"] = time.time_ns()
    with Path(os.environ["AF_GRAPH_AUDIT"]).open("a", encoding="utf-8") as h: h.write(json.dumps(event, sort_keys=True)+"\n")
def serial_graph_call(callback):
    lock_path = Path(".graphauthor_workspace.lock")
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o644)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX)
        return callback()
    finally:
        fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)
def main():
    if len(sys.argv) != 3 or sys.argv[1] not in ALLOWED: raise SystemExit("usage: graphauthor_access.py OPERATION JSON")
    operation, args = sys.argv[1], json.loads(sys.argv[2])
    if not isinstance(args, dict): raise SystemExit("arguments must be an object")
    if {"search", "read_cypher", "include_content", "context_ref", "graph_version", "explain"} & set(args): raise SystemExit("not exposed by this frozen treatment")
    if operation == "run_ephemeral_traversal":
        try: validate_frozen_ephemeral_program(args.get("program") or {})
        except ExcludedEphemeralOperation as exc:
            audit({"event":"graph_operation_rejected", "operation":operation, "arguments":args, "error":str(exc), "before_execution":True})
            raise SystemExit(str(exc))
    silence=io.StringIO(); surface=None
    def run():
        nonlocal surface
        try:
            with contextlib.redirect_stdout(silence), contextlib.redirect_stderr(silence):
                surface=Surface(Path("view.lbug"), capabilities=("query",))
                if operation == "describe": result=surface.describe()
                elif operation == "run_ephemeral_traversal": result=surface.run_ephemeral_traversal(args.get("program") or {}, args.get("parameters"), evidence="packet")
                else: result=getattr(Retrieve(surface), operation)(**args)
            audit_packet = None
            ref = result.get("audit_evidence_ref") if isinstance(result,dict) else None
            if ref: audit_packet = surface._traversal_audit_packets.get(ref, {})
            audit({"event":"graph_operation", "operation":operation, "arguments":args, "outcome":result.get("outcome"), "returned_ids":walk(result,"id") + walk(result,"answer_node_ids"), "used_relation_ids":walk(audit_packet,"relation_id") + walk(result,"relation_id"), "receipt":result.get("execution_receipt"), "audit_evidence_ref":ref})
            print(json.dumps(result, sort_keys=True))
            return result
        except Exception as exc:
            audit({"event":"graph_operation_failure", "operation":operation, "arguments":args, "error":repr(exc)})
            raise
        finally:
            if surface:
                with contextlib.redirect_stdout(silence), contextlib.redirect_stderr(silence): surface.close()
    serial_graph_call(run)
if __name__ == "__main__": main()

"""Acceptance gate for the frozen Graphauthor one-off programming v1 surface.

These are apparatus checks, not experiment cases.  They exercise the actual
no-graph.md path that the frozen-view graph treatment will use.
"""

from __future__ import annotations

from mcp_server.graph_contract import load_graph_contract
from mcp_server.surface import Surface
from tests.workbook_graph_fixture import narrative_fixture


def _scratch_surface(tmp_path) -> Surface:
    db_path, _ = narrative_fixture(tmp_path / "scratch-task-graph.lbug")
    # The fixture's contract is intentionally not called graph.md.  With no
    # explicit path, this is the minimal-contract path used by the experiment.
    return Surface(db_path)


def _event_sets_program(*, result_mode: str = "compact") -> dict:
    return {
        "name": "compare_participation",
        "steps": [
            {"op": "lookup", "references": ["character:ilma"], "assign": "ilma"},
            {"op": "lookup", "references": ["character:torv"], "assign": "torv"},
            {
                "op": "expand", "from": "$ilma", "predicates": ["participates_in"],
                "direction": "outgoing", "depth": 1, "assign": "ilma_events",
            },
            {
                "op": "expand", "from": "$torv", "predicates": ["participates_in"],
                "direction": "outgoing", "depth": 1, "assign": "torv_events",
            },
            {
                "op": "difference", "of": "$ilma_events", "minus": "$torv_events",
                "assign": "only_ilma",
            },
            {
                "op": "intersection", "of": "$ilma_events", "with": "$torv_events",
                "assign": "shared_events",
            },
        ],
        "collect": "$only_ilma + $shared_events",
        "answers": {
            "only_ilma": "$only_ilma",
            "shared_events": "$shared_events",
        },
        "result_mode": result_mode,
    }


def test_describe_is_representation_only_and_sufficient_to_program(tmp_path):
    surface = _scratch_surface(tmp_path)
    try:
        description = surface.describe()

        assert set(description) == {
            "contract_version", "graph_version", "trace_id", "kind", "outcome",
            "source", "schema_version", "schema_fingerprint", "node_kinds",
            "predicates", "capabilities",
        }
        assert description["predicates"]["participates_in"]["carrier"] == "EXPRESSES"
        assert description["predicates"]["participates_in"]["direction"] == "directed"
        assert "find_paths" in description["capabilities"]["ephemeral_program"]["ops"]
        assert description["capabilities"]["ephemeral_program"]["result_modes"] == [
            "full", "compact"
        ]
    finally:
        surface.close()


def test_no_graph_md_derives_contract_and_supports_predicate_path(tmp_path):
    surface = _scratch_surface(tmp_path)
    try:
        out = surface.run_ephemeral_traversal(
            {
                "name": "predicate_path_from_scratch_schema",
                "steps": [
                    {"op": "lookup", "references": ["character:ilma"], "assign": "source"},
                    {"op": "lookup", "references": ["place:the-terrace"], "assign": "target"},
                    {
                        "op": "find_paths", "from": "$source", "to": "$target",
                        "predicates": ["participates_in", "occurs_at"],
                        "direction": "outgoing", "max_hops": 2, "assign": "paths",
                    },
                ],
                "collect": "$paths",
                "answers": {"paths": "$paths"},
                "result_mode": "compact",
            },
            evidence="packet",
        )

        assert out["outcome"] == "FOUND"
        assert "place:the-terrace" in out["answers"]["paths"]
        assert out["execution_receipt"]["operations"][-1]["result_count"] == 3
        assert out["execution_receipt"]["format_fingerprint"].startswith("gschema_")
    finally:
        surface.close()
